arguments.content:
* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: 'Inter', sans-serif;
    background-color: #000000;
    color: #FFFFFF;
    line-height: 1.5;
    overflow-x: hidden;
}

a {
    color: inherit;
    text-decoration: none;
}

.btn {
    display: inline-block;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 600;
    text-align: center;
    transition: background-color 0.2s ease;
}

.btn-primary {
    background-color: #E50914;
    color: white;
}

.btn-primary:hover {
    background-color: #C11119;
}

.btn-small {
    padding: 0.4rem 1rem;
    font-size: 0.9rem;
}

.btn-large {
    padding: 0.8rem 1.5rem;
    font-size: 1.25rem;
}

.header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem 5%;
    position: relative;
    z-index: 10;
}

.logo {
    font-size: 2.5rem;
    font-weight: 800;
    color: #E50914;
    text-transform: uppercase;
    letter-spacing: -1px;
}

.header-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
}

.lang-select {
    background: transparent;
    color: white;
    border: 1px solid rgba(255,255,255,0.3);
    padding: 0.4rem 0.5rem;
    border-radius: 4px;
    font-size: 0.9rem;
    outline: none;
}
.lang-select option {
    background: #000;
}

.hero-bg {
    position: relative;
    min-height: 80vh;
    border-bottom: 8px solid #232323;
}

.hero-bg::before {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: url('https://images.unsplash.com/photo-1598899134739-24c46f58b8c0?auto=format&fit=crop&w=1920&q=80') center/cover;
    opacity: 0.4;
    z-index: 0;
}

.hero-bg::after {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: linear-gradient(to top, rgba(0,0,0,1) 0, rgba(0,0,0,0.3) 60%, rgba(0,0,0,0.8) 100%);
    z-index: 1;
}

.hero {
    position: relative;
    z-index: 2;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 8rem 5% 4rem;
    max-width: 900px;
    margin: 0 auto;
}

.hero-title {
    font-size: 3.5rem;
    font-weight: 800;
    margin-bottom: 1rem;
    line-height: 1.1;
}

.hero-subtitle {
    font-size: 1.5rem;
    margin-bottom: 1.5rem;
    font-weight: 400;
}

.email-capture {
    width: 100%;
    margin-top: 1rem;
}

.email-capture p {
    font-size: 1.25rem;
    margin-bottom: 1rem;
}

.email-form {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
    max-width: 700px;
    margin: 0 auto;
}

.email-form input {
    flex: 1;
    padding: 1rem;
    font-size: 1rem;
    border: 1px solid rgba(255,255,255,0.3);
    border-radius: 4px;
    background: rgba(0,0,0,0.5);
    color: white;
}

.section {
    padding: 4rem 5%;
    border-bottom: 8px solid #232323;
}

.section-title {
    font-size: 2rem;
    margin-bottom: 2rem;
    font-weight: 800;
}

/* Trending Carousel */
.trending-container {
    position: relative;
    display: flex;
    align-items: center;
}

.carousel {
    display: flex;
    gap: 1.5rem;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
    padding-bottom: 1rem;
    width: 100%;
}

.carousel::-webkit-scrollbar {
    display: none;
}

.carousel-item {
    min-width: 200px;
    height: 300px;
    background: #141414;
    border-radius: 8px;
    position: relative;
    scroll-snap-align: start;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    transition: transform 0.2s;
    border: 1px solid #333;
}

.carousel-item:hover {
    transform: scale(1.05);
}

.carousel-poster {
    width: 100%;
    height: 100%;
    object-fit: cover;
    opacity: 0.6;
}

.carousel-rank {
    position: absolute;
    bottom: -15px;
    left: -10px;
    font-size: 8rem;
    font-weight: 800;
    color: transparent;
    -webkit-text-stroke: 3px #FFFFFF;
    line-height: 1;
    z-index: 2;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
}

.carousel-title {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-weight: 800;
    font-size: 1.25rem;
    z-index: 1;
    text-align: center;
    color: #fff;
    width: 80%;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
}

.carousel-arrow {
    position: absolute;
    right: 0;
    background: rgba(0,0,0,0.7);
    color: white;
    border: none;
    width: 50px;
    height: 100px;
    font-size: 2.5rem;
    cursor: pointer;
    z-index: 10;
    border-radius: 4px 0 0 4px;
    transition: background 0.2s;
}
.carousel-arrow:hover {
    background: rgba(0,0,0,0.9);
}

/* Features */
.features-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1.5rem;
}

.feature-card {
    background: linear-gradient(135deg, #1f1f1f, #141414);
    padding: 2rem;
    border-radius: 12px;
    position: relative;
    min-height: 250px;
}

.feature-card h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
    font-weight: 600;
}

.feature-card p {
    color: #B3B3B3;
    font-size: 1rem;
}

.feature-icon {
    position: absolute;
    bottom: 1.5rem;
    right: 1.5rem;
    font-size: 2.5rem;
    opacity: 0.5;
}

/* FAQ */
.faq-list {
    max-width: 800px;
    margin: 0 auto;
}

.faq-item {
    margin-bottom: 0.5rem;
}

.faq-question {
    background: #2d2d2d;
    padding: 1.5rem;
    font-size: 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    transition: background 0.2s;
}

.faq-question:hover {
    background: #414141;
}

.faq-icon {
    font-size: 2.5rem;
    line-height: 1;
    font-weight: 300;
    transition: transform 0.2s;
}

.faq-answer {
    background: #2d2d2d;
    padding: 0 1.5rem;
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease, padding 0.3s ease;
    border-top: 1px solid #000;
    font-size: 1.25rem;
}

.faq-item.active .faq-answer {
    padding: 1.5rem;
    max-height: 800px;
}

.faq-item.active .faq-icon {
    transform: rotate(45deg);
}

/* Bottom CTA */
.bottom-cta {
    text-align: center;
    padding: 4rem 5%;
    border-bottom: 8px solid #232323;
}

/* Footer */
.footer {
    padding: 4rem 5%;
    color: #B3B3B3;
    max-width: 1000px;
    margin: 0 auto;
}

.footer-prompt {
    margin-bottom: 2rem;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1rem;
    margin-bottom: 2rem;
}

.footer-link {
    font-size: 0.9rem;
    text-decoration: underline;
}

.footer-bottom {
    margin-top: 2rem;
    font-size: 0.8rem;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

/* Login Page Specifics */
.login-bg {
    min-height: 100vh;
    background: url('https://images.unsplash.com/photo-1598899134739-24c46f58b8c0?auto=format&fit=crop&w=1920&q=80') center/cover;
    position: relative;
}

.login-bg::before {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0,0,0,0.6);
}

.login-container {
    position: relative;
    z-index: 2;
    background: rgba(0,0,0,0.75);
    max-width: 450px;
    margin: 0 auto;
    padding: 4rem;
    border-radius: 4px;
    min-height: 600px;
}

.login-title {
    font-size: 2rem;
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.login-form {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.login-form input {
    padding: 1rem;
    background: #333;
    border: none;
    border-radius: 4px;
    color: white;
    font-size: 1rem;
}

.login-btn {
    margin-top: 1.5rem;
    width: 100%;
}

.login-subtext {
    margin-top: 1rem;
    color: #B3B3B3;
}

.help-toggle {
    margin-top: 1rem;
    color: #B3B3B3;
    cursor: pointer;
    font-size: 0.9rem;
}
.help-toggle:hover {
    text-decoration: underline;
}

.help-content {
    display: none;
    margin-top: 1rem;
    color: #B3B3B3;
    font-size: 0.9rem;
}

.help-content.active {
    display: block;
}

.login-page-wrapper .header {
    background: linear-gradient(to bottom, rgba(0,0,0,0.8), rgba(0,0,0,0));
}

.login-page-wrapper .footer {
    background: rgba(0,0,0,0.75);
    border-top: 1px solid #737373;
    max-width: 100%;
    margin-top: 2rem;
}

@media (max-width: 768px) {
    .hero-title { font-size: 2.5rem; }
    .hero-subtitle { font-size: 1.2rem; }
    .email-form { flex-direction: column; }
    .footer-grid { grid-template-columns: repeat(2, 1fr); }
    .login-container { padding: 2rem; width: 100%; min-height: 100vh; background: #000; border-radius: 0; }
    .login-bg::before { display: none; }
    .login-bg { background: #000; }
    .login-page-wrapper .footer { border-top: none; }
}

@media (max-width: 480px) {
    .hero-title { font-size: 2rem; }
    .footer-grid { grid-template-columns: 1fr; }
    .faq-question { font-size: 1.25rem; }
}

